using System;using System.Linq;using UnityEditor;using UnityEngine;using RoadGunner.Editor;
public static class WidenGreenwoodPocket{public static string Main(){if(EditorApplication.isPlaying)throw new InvalidOperationException("Stop Play");var l=RoadGunnerLevelAuthoring.Current;var q=Quaternion.Euler(0,45,0);var boundary=l.obstaclesRoot.Find("01 · Rock boundaries and islands");foreach(Transform t in boundary){var p=Quaternion.Inverse(q)*t.position;if(t.name=="Cliff"&&Mathf.Abs(p.x-37)<.2f&&Mathf.Abs(p.z-47)<.2f){t.position=AstraZone01Builder.World(40.5f,47);PrefabUtility.RecordPrefabInstancePropertyModifications(t);}}foreach(Transform section in l.decorationRoot)if(section.name.StartsWith("Cliff crown"))foreach(Transform t in section){var p=Quaternion.Inverse(q)*t.position;if(Mathf.Abs(p.x-36.2f)<.2f&&Mathf.Abs(p.z-47.5f)<.2f){t.position=AstraZone01Builder.World(39.7f,47.5f,t.position.y);PrefabUtility.RecordPrefabInstancePropertyModifications(t);}}RoadGunnerLevelAuthoring.Save(l);return "Pocket entrance widened by 3.5 metres; navigation rebaked";}}